<script setup lang="ts">
import {computed,ref} from 'vue';
import {state,change,ui} from '../state';
import {editSkillLink,type LinkKind} from '../domain/skill-links';
const query=ref(''),stream=ref(''),theme=ref(''),selected=ref(''),parent=ref(''),kind=ref<LinkKind>('required'),linkQuery=ref('');
const currentLinksOnly=ref(false);
const all=computed(()=>state.value!.requirements);
const current=computed(()=>all.value.find(r=>r.id===selected.value));
const themes=computed(()=>[...new Set(all.value.flatMap(r=>(r.theme_tags as string[]|undefined)??r.tags))].sort());
const filtered=computed(()=>currentLinksOnly.value&&current.value?all.value.filter(r=>r.id===selected.value||relation(r.id)!==''):all.value.filter(r=>(!stream.value||r.stream===stream.value)&&(!theme.value||((r.theme_tags as string[]|undefined)??r.tags).includes(theme.value))&&[r.text,r.id].join(' ').toLowerCase().includes(query.value.toLowerCase())));
const choices=computed(()=>all.value.filter(r=>r.id!==selected.value&&[r.text,r.id,'Stage '+r.stage].join(' ').toLowerCase().includes(linkQuery.value.toLowerCase())));
const links=computed(()=>current.value?[...current.value.prerequisites.map(id=>({id,kind:'required' as LinkKind})),...(current.value.suggested_links??[]).map(l=>({id:l.id,kind:'recommended' as LinkKind}))]:[]);
const dependents=computed(()=>all.value.filter(r=>r.prerequisites.includes(selected.value)||r.suggested_links?.some(l=>l.id===selected.value)));
function relation(id:string){if(current.value?.prerequisites.includes(id))return 'required';if(current.value?.suggested_links?.some(l=>l.id===id))return 'recommended';if(dependents.value.some(r=>r.id===id))return 'dependent';return '';}
function choose(id:string){selected.value=id;parent.value='';linkQuery.value='';ui.requirementId='';}
function update(id:string,type:LinkKind,remove=false){change('Before skill tree link edit',s=>{s.requirements=editSkillLink(s.requirements,selected.value,id,type,remove);});}
</script>
<template><section><p>Create curriculum links by selecting the statement that depends on another skill, then choosing the skill that comes before it. Edits apply to the shared curriculum and create a recovery checkpoint.</p><div class="toolbar filter-panel"><label>Find statements<input v-model="query" type="search"></label><label>Stream<select v-model="stream"><option value="">All streams</option><option v-for="s in [...new Set(all.map(r=>r.stream))]" :key="s">{{s}}</option></select></label><label>Theme<select v-model="theme"><option value="">All themes</option><option v-for="t in themes" :key="t">{{t}}</option></select></label><label class="mapper-link-toggle"><input v-model="currentLinksOnly" type="checkbox" role="switch" :disabled="!current"><span class="mapper-switch-track" aria-hidden="true"></span><span>Current links only<small>{{!current?'Select a statement first':currentLinksOnly?'Showing the selected statement, prerequisites and leads-to links; other filters are paused.':'Show only direct connections to the selected statement'}}</small></span></label></div><div class="mapper-legend"><span>→ Mandatory prerequisite</span><span>⇢ Recommended prerequisite</span><span>↗ Depends on selected statement</span></div><div class="skill-mapper-layout"><div class="requirement-grid"><section v-for="n in [1,2,3]" :key="n" class="stage-column"><h2>Stage {{n}}</h2><button v-for="r in filtered.filter(r=>r.stage===n)" :key="r.id" :class="['mapper-node',relation(r.id),{selected:selected===r.id}]" @click="choose(r.id)"><span>{{relation(r.id)==='required'?'→':relation(r.id)==='recommended'?'⇢':relation(r.id)==='dependent'?'↗':'◇'}}</span><span>{{r.text}}<small>{{r.stream}} · {{r.prerequisites.length}} required · {{r.suggested_links?.length??0}} recommended</small></span></button></section></div><aside class="panel mapper-editor"><template v-if="current"><p class="eyebrow">Edit incoming links</p><h2>{{current.text}}</h2><p>Stage {{current.stage}} · {{current.stream}}</p><form @submit.prevent="update(parent,kind)"><label>Find a preceding skill<input v-model="linkQuery" type="search" placeholder="Search statement or stage"></label><label>Preceding skill<select v-model="parent" required><option value="" disabled>Choose a statement</option><option v-for="r in choices" :key="r.id" :value="r.id">Stage {{r.stage}} · {{r.text}}</option></select></label><label>Link type<select v-model="kind"><option value="required">→ Mandatory prerequisite</option><option value="recommended">⇢ Recommended prerequisite</option></select></label><button class="primary" :disabled="!parent">Add link</button></form><h3>Before this statement</h3><div v-for="link in links" :key="link.kind+link.id" :class="['mapper-link',link.kind]"><button class="text-link" @click="choose(link.id)">{{link.kind==='required'?'→':'⇢'}} {{all.find(r=>r.id===link.id)?.text}}</button><button @click="update(link.id,link.kind,true)">Remove</button></div><p v-if="!links.length">No preceding skills linked.</p><h3>Leads to</h3><button v-for="r in dependents" :key="r.id" class="mapper-node" @click="choose(r.id)">↗ {{r.text}}</button><p v-if="!dependents.length">No later statements linked yet.</p></template><template v-else><h2>Build the skill flow</h2><p>Select a statement to create, inspect or remove its incoming links.</p></template></aside></div></section></template>
